shell_commands:
node --input-type=module -e "
import {readFileSync} from 'node:fs';
import {statementCoverage} from './node_modules/@re-cinq/eslint-plugin-re-lint/dist/vendor/spec/spec-status-coverage.js';
const content = readFileSync('specs/hal-engine-tool-input-validation/spec.md', 'utf8');
const {testable, linked} = statementCoverage(content);
console.log('testable:', testable, 'linked:', linked);
const tier = linked === 0 ? 'none' : (linked < testable ? 'partial' : 'full');
console.log('expected status:', {none:'draft', partial:'in-progress', full:'shipped', vacuous:'vacuous'}[tier]);
console.log('declared:', content.match(/\| Status \| ([^|]+) \|/)[1].trim());
"

node --input-type=module -e "
import path from 'node:path';
import {buildLinkIndex, readSpecFiles} from './node_modules/@re-cinq/eslint-plugin-re-lint/dist/rules/lib/spec-link-index.mjs';
const index = buildLinkIndex(readSpecFiles(process.cwd(), ['specs', 'adrs']));
for (const f of ['src/orchestration/tools/registry.test.ts', 'src/orchestration/tools/registry.acceptance.test.ts']) {
  const entry = index.get(f);
  const lines = entry ? [...entry.lines].sort((a,b)=>a-b) : [];
  console.log(f, '→ links at lines:', JSON.stringify(lines));
}
"
